/**
 * Every failure crossing the FFI boundary. `class` is the SPEC-v2 §2.7
 * spelling; the hand-written layers map it to their `ErrorClass`.
 */

enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    /**
     * A core `V2Error`: decode, check, digest, journal, configuration.
     */
    case Protocol(`class`: String, detail: String
    )
    /**
     * A `V2SignError`: signing refused or the signer failed.
     */
    case Signing(`class`: String, kind: String, detail: String
    )
    /**
     * An internal failure, never a protocol result: `panic` (a caught Rust
     * panic), `poisoned` (a handle a panic left unusable), or
     * `random_source` (the operating-system random source failed).
     */
    case Internal(kind: String, detail: String
    )






    var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension FfiError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .Protocol(
            `class`: try FfiConverterString.read(from: &buf),
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Signing(
            `class`: try FfiConverterString.read(from: &buf),
            kind: try FfiConverterString.read(from: &buf),
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Internal(
            kind: try FfiConverterString.read(from: &buf),
            detail: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {





        case let .Protocol(`class`,detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(`class`, into: &buf)
            FfiConverterString.write(detail, into: &buf)


        case let .Signing(`class`,kind,detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(`class`, into: &buf)
            FfiConverterString.write(kind, into: &buf)
            FfiConverterString.write(detail, into: &buf)


        case let .Internal(kind,detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(kind, into: &buf)
            FfiConverterString.write(detail, into: &buf)

        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
func FfiConverterTypeFfiError_lift(_ buf: RustBuffer) throws -> FfiError {
    return try FfiConverterTypeFfiError.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
func FfiConverterTypeFfiError_lower(_ value: FfiError) -> RustBuffer {
    return FfiConverterTypeFfiError.lower(value)
}



