 */

indirect enum FfiParamsValue: Equatable, Hashable {

    case null
    case bool(value: Bool
    )
    case int(value: Int64
    )
    case str(value: String
    )
    case array(items: [FfiParamsValue]
    )
    case object(entries: [String: FfiParamsValue]
    )





}

